<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue'
import type {Stage3Api,Workbench} from '../../../business-common/stage3/types'
import {label,money,date} from '../../../business-common/stage3/presentation'
import BaseCard from '../BaseCard.vue'
import AppButton from '../AppButton.vue'
const props=defineProps<{api:Stage3Api;refreshKey?:number}>();const emit=defineEmits<{orders:[filter:string];verify:[];messages:[]}>()
const data=ref<Workbench|null>(null),lastSuccessAt=ref<string|null>(null),error=ref(''),loading=ref(false);let ticket=0
async function load(){const run=++ticket,owner=props.api.owner();loading.value=true;error.value='';try{const value=await props.api.workbench();if(run===ticket&&owner===props.api.owner()){data.value=value;lastSuccessAt.value=value.serverTime}}catch(e){if(run===ticket){data.value=null;error.value=e instanceof Error?e.message:'订单待办暂不可用。'}}finally{if(run===ticket)loading.value=false}}
watch(()=>props.api.owner(),()=>{ticket++;data.value=null;lastSuccessAt.value=null;load()},{immediate:true});watch(()=>props.refreshKey,load);onBeforeUnmount(()=>{ticket++;data.value=null})
</script>
<template><view class="s3-view workbench"><BaseCard><view class="s3-view head"><text class="s3-text title">履约待办</text><AppButton size="compact" variant="secondary" :disabled="loading" @click="load">刷新待办</AppButton><AppButton size="compact" variant="secondary" @click="emit('orders','ALL')">全部订单</AppButton></view><text v-if="loading&&!data" class="s3-text meta">正在读取当前店铺待办…</text><text v-if="error" class="s3-text error">{{error}}</text><text v-if="error" class="s3-text meta">{{lastSuccessAt?'上次成功读取：'+date(lastSuccessAt):'尚无成功读取记录；当前统计不可用。'}}</text><AppButton v-if="error" variant="secondary" @click="load">重新读取</AppButton><text v-if="data&&!data.countsAvailable" class="s3-text meta">当前履约操作尚未开放，待办数量暂不可用。</text><view v-if="data?.countsAvailable" class="s3-view grid"><view v-for="(count,phase) in data.counts" :key="phase" class="s3-view metric" @click="emit('orders',['WAIT_PICKUP','WAIT_VERIFY'].includes(String(phase))?'PICKUP':['DELIVERING','DELIVERED','SHIPPED'].includes(String(phase))?'WAIT_RECEIVE':'WAIT_MERCHANT')"><text class="s3-text">{{label(String(phase))}}</text><text class="s3-text number">{{count}}</text></view></view></BaseCard><BaseCard v-if="data"><text class="s3-text title">今日订单与成交</text><text class="s3-text meta">{{data.date}} · 北京时间自然日</text><view class="s3-view grid"><view class="s3-view metric"><text class="s3-text">今日订单</text><text class="s3-text number">{{data.todayOrders}}</text></view><view class="s3-view metric"><text class="s3-text">今日实付成交额</text><text class="s3-text amount">¥{{money(data.turnoverCent)}}</text></view></view><text class="s3-text meta">成交额按本店订单实际付款时间统计；订单数按创建时间统计。</text><text class="s3-text meta">更新 {{date(data.serverTime)}}</text></BaseCard><view class="s3-view actions"><AppButton v-if="data?.canVerify" @click="emit('verify')">扫码 / 输码核销</AppButton><AppButton v-if="data?.canViewMessages" variant="secondary" @click="emit('messages')">订单消息</AppButton></view></view></template>
<style scoped lang="scss">.workbench{display:flex;flex-direction:column;gap:16px}.head{display:flex;gap:12px;align-items:center;justify-content:space-between}.title{display:block;font-size:18px;font-weight:700}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:16px 0}.metric{padding:16px 12px;border-radius:12px;background:$color-group-bg;min-height:90px;box-sizing:border-box;font-size:15px}.metric>.s3-text{display:block;overflow-wrap:anywhere}.number{font-size:30px;font-weight:700;color:$color-primary}.amount{font-size:22px;font-weight:700;color:$color-primary}.meta{display:block;color:$color-text-secondary;font-size:13px;line-height:1.7;margin-top:8px}.error{color:$color-error;display:block;margin:12px 0}.actions{display:flex;gap:12px;flex-wrap:wrap}.actions :deep(.app-button){flex:1;min-width:120px}</style>
